% 已知參數
W = 309.5;          % kg
g = 9.81;           % m/s^2
h = 0.284;          % m
L = 1.55;           % m (軸距)
d = 1.25;           % m (輪距)
ax = 0.3*g;         % m/s^2
ay = 1.5*g;         % m/s^2

% 總重力
Fz = W*g;

% 靜態分配 (前後比例)
Fzf = 0.48*Fz;      % 前軸
Fzr = 0.52*Fz;      % 後軸
Ffl0 = Fzf/2;       % 前左
Ffr0 = Fzf/2;       % 前右
Frl0 = Fzr/2;       % 後左
Frr0 = Fzr/2;       % 後右

% 縱向負載轉移
dFx = W*ax*h/L;

% 橫向負載轉移
dFy = W*ay*h/d;

%% 方法1：均分法 (mg/4 + 修正)
Ffl1 = Ffl0 - dFx/2 - dFy/2;
Ffr1 = Ffr0 - dFx/2 + dFy/2;
Frl1 = Frl0 + dFx/2 - dFy/2;
Frr1 = Frr0 + dFx/2 + dFy/2;

%% 方法2：先前後分配，再左右分配
Fzf_dyn = Fzf-dFx;
Fzr_dyn = Fzr+dFx;
% 再左右分配
Ffl2 = Fzf_dyn/2 - dFy/2;
Ffr2 = Fzf_dyn/2 + dFy/2;
Frl2 = Fzr_dyn/2 - dFy/2;
Frr2 = Fzr_dyn/2 + dFy/2;

%% 方法3：先左右分配，再前後分配
% 先算左右
Fzl_dyn = (Fz/2) - dFy;   % 左側動態
Fzright_dyn2 = (Fz/2) + dFy;  % 右側動態
% 再前後分配
Ffl3 = (Fz/2)*0.48 - dFy/2 - dFx/2;
Frl3 = (Fz/2)*0.52 - dFy/2 + dFx/2;
Ffr3 = (Fz/2)*0.48 + dFy/2 - dFx/2;
Frr3 = (Fz/2)*0.52 + dFy/2 + dFx/2;

%% 顯示結果
fprintf('方法1 均分法: FL=%.1f, FR=%.1f, RL=%.1f, RR=%.1f\n',Ffl1,Ffr1,Frl1,Frr1); %[output:952d4ed2]
fprintf('方法2 先前後再左右: FL=%.1f, FR=%.1f, RL=%.1f, RR=%.1f\n',Ffl2,Ffr2,Frl2,Frr2); %[output:6a62d1fa]
fprintf('方法3 先左右再前後: FL=%.1f, FR=%.1f, RL=%.1f, RR=%.1f\n',Ffl3,Ffr3,Frl3,Frr3); %[output:2577015f]

%% 作圖比較
labels = {'FL','FR','RL','RR'};
values1 = [Ffl1,Ffr1,Frl1,Frr1];
values2 = [Ffl2,Ffr2,Frl2,Frr2];
values3 = [Ffl3,Ffr3,Frl3,Frr3];

figure; %[output:8d4288d6]
bar([values1; values2; values3]') %[output:8d4288d6]
legend('方法1 均分','方法2 前後→左右','方法3 左右→前後','Location','best'); %[output:8d4288d6]
set(gca,'XTickLabel',labels); %[output:8d4288d6]
ylabel('輪胎負載 (N)'); %[output:8d4288d6]
title('三種分配方法比較'); %[output:8d4288d6]

